const textRoutes = {"/index.html":{"body":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>Zenzo</title>\n    <meta name=\"description\" content=\"Collector storefront for selling Hot Wheels and 1:64 die-cast cars.\">\n    <link rel=\"preload\" as=\"image\" href=\"assets/hero-shelf-fast.jpg\">\n    <link rel=\"preload\" as=\"image\" href=\"assets/zenzo-logo-mark.png\">\n    <link rel=\"stylesheet\" href=\"styles.css?v=zenzo-race-theme-18\">\n  </head>\n  <body>\n    <header class=\"hero\">\n      <img src=\"assets/hero-shelf-fast.jpg\" alt=\"Display shelf with collectible die-cast toy cars\" class=\"hero__image\" width=\"1280\" height=\"683\" fetchpriority=\"high\">\n      <div class=\"hero__shade\"></div>\n      <nav class=\"topbar\" aria-label=\"Primary navigation\">\n        <a class=\"brand\" href=\"#catalog\" aria-label=\"Zenzo home\">\n          <span class=\"brand__logo-frame\"><img src=\"assets/zenzo-logo-mark.png\" alt=\"Zenzo\" class=\"brand__logo\" width=\"520\" height=\"138\" fetchpriority=\"high\"></span>\n        </a>\n        <button class=\"cart-button\" id=\"cartButton\" type=\"button\" aria-controls=\"cartPanel\" aria-expanded=\"false\">\n          <span aria-hidden=\"true\">Cart</span>\n          <span class=\"cart-button__count\" id=\"cartCount\">0</span>\n        </button>\n      </nav>\n      <section class=\"hero__content\" aria-labelledby=\"pageTitle\">\n        <h1 id=\"pageTitle\" class=\"hero__headline\">\n          <span class=\"hero__line hero__line--primary\">Race-ready</span>\n          <span class=\"hero__line hero__line--accent\">Hot Wheels</span>\n        </h1>\n        <div class=\"hero__motion\" aria-hidden=\"true\">\n          <span></span>\n          <span></span>\n          <span></span>\n        </div>\n        <p class=\"hero__copy\">Your one-stop destination for collectibles. Explore Hot Wheels, figurines, and 3D printed collectibles, from iconic diecast cars to custom designed display pieces.</p>\n        <p class=\"hero__tagline\">Built for collectors, by collectors.</p>\n        <a class=\"primary-link\" href=\"#catalog\">Shop the drop</a>\n      </section>\n    </header>\n\n    <main>\n      <section class=\"showcase\" aria-labelledby=\"showcaseTitle\">\n        <div class=\"showcase__copy\">\n          <p class=\"eyebrow\">Collector display</p>\n          <h2 id=\"showcaseTitle\">Fresh drops, shelf-ready pieces</h2>\n          <p>Browse sealed packs and collectible 1:64 finds curated for Indian buyers.</p>\n        </div>\n        <img src=\"assets/collector-shelf-v2.png?v=zenzo-race-theme-18\" alt=\"Collector shelf with die-cast toy cars and sealed packs\" loading=\"lazy\">\n      </section>\n\n      <section class=\"collections\" aria-labelledby=\"collectionsTitle\">\n        <div class=\"collections__intro\">\n          <p class=\"eyebrow\">Collections</p>\n          <h2 id=\"collectionsTitle\">Browse collections</h2>\n        </div>\n        <div class=\"collection-list\" aria-label=\"Collection filter\">\n          <button class=\"collection-card collection-card--all is-active\" type=\"button\" data-collection=\"all\">\n            <strong>All collectibles</strong>\n          </button>\n          <button class=\"collection-card collection-card--hotwheels\" type=\"button\" data-collection=\"Hot Wheels\">\n            <strong>Hot Wheels</strong>\n          </button>\n          <button class=\"collection-card collection-card--figurines\" type=\"button\" data-collection=\"Figurines\">\n            <strong>Figurines</strong>\n          </button>\n          <button class=\"collection-card collection-card--printed\" type=\"button\" data-collection=\"3D collectibles\">\n            <strong>3D collectibles</strong>\n          </button>\n        </div>\n      </section>\n\n      <section class=\"toolbar\" aria-label=\"Catalog controls\">\n        <label class=\"search\">\n          <span class=\"sr-only\">Search cars</span>\n          <input id=\"searchInput\" type=\"search\" placeholder=\"Search name, collection, series\">\n        </label>\n        <div class=\"filter-group\" aria-label=\"Condition filter\">\n          <button class=\"chip is-active\" type=\"button\" data-condition=\"all\">All</button>\n          <button class=\"chip\" type=\"button\" data-condition=\"Sealed Pack\">Sealed Pack</button>\n          <button class=\"chip\" type=\"button\" data-condition=\"Sealed\">Sealed</button>\n        </div>\n        <label class=\"select-label\">\n          <span class=\"sr-only\">Sort products</span>\n          <select id=\"sortSelect\">\n            <option value=\"featured\">Featured</option>\n            <option value=\"priceAsc\">Price low to high</option>\n            <option value=\"priceDesc\">Price high to low</option>\n            <option value=\"yearDesc\">Newest year</option>\n          </select>\n        </label>\n      </section>\n\n      <section class=\"catalog\" id=\"catalog\" aria-labelledby=\"catalogTitle\">\n        <div class=\"section-heading\">\n          <p class=\"eyebrow\">Available now</p>\n          <h2 id=\"catalogTitle\">Current listings</h2>\n        </div>\n        <div class=\"product-grid\" id=\"productGrid\"></div>\n        <p class=\"empty-state\" id=\"emptyState\" hidden>No matching cars found.</p>\n      </section>\n    </main>\n\n    <aside class=\"cart-panel\" id=\"cartPanel\" aria-label=\"Shopping cart\" aria-hidden=\"true\">\n      <div class=\"cart-panel__header\">\n        <h2>Your cart</h2>\n        <button class=\"icon-button\" id=\"closeCart\" type=\"button\" aria-label=\"Close cart\">x</button>\n      </div>\n      <div class=\"cart-items\" id=\"cartItems\"></div>\n      <div class=\"cart-summary\">\n        <div class=\"cart-summary__row\">\n          <span>Subtotal</span>\n          <strong id=\"cartSubtotal\">$0.00</strong>\n        </div>\n        <p>UPI payments are handled through secure checkout before dispatch.</p>\n        <a class=\"checkout-link\" id=\"checkoutLink\" href=\"checkout.html\">Checkout</a>\n      </div>\n    </aside>\n    <div class=\"scrim\" id=\"scrim\" hidden></div>\n\n    <footer>\n      <p>Zenzo collector resale shop. Not affiliated with Mattel or Hot Wheels.</p>\n      <a class=\"footer-admin-link\" href=\"admin.html\">Admin</a>\n    </footer>\n\n    <script src=\"app.js?v=zenzo-race-theme-18\"></script>\n  </body>\n</html>\n","type":"text/html; charset=utf-8"},"/product.html":{"body":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>Product | Zenzo</title>\n    <meta name=\"description\" content=\"Zenzo Hot Wheels product details and UPI checkout.\">\n    <link rel=\"stylesheet\" href=\"styles.css?v=zenzo-race-theme-18\">\n  </head>\n  <body class=\"checkout-page product-page\">\n    <main class=\"checkout-shell\">\n      <nav class=\"checkout-nav\" aria-label=\"Product navigation\">\n        <a class=\"brand\" href=\"index.html#catalog\" aria-label=\"Zenzo home\">\n          <span class=\"brand__logo-frame\"><img src=\"assets/zenzo-logo-mark.png\" alt=\"Zenzo\" class=\"brand__logo\" width=\"520\" height=\"138\"></span>\n        </a>\n        <a class=\"primary-link\" href=\"index.html#catalog\">Back to shop</a>\n      </nav>\n\n      <section class=\"product-detail\" id=\"productDetail\" aria-live=\"polite\"></section>\n    </main>\n\n    <script src=\"product.js?v=zenzo-race-theme-18\"></script>\n  </body>\n</html>\n","type":"text/html; charset=utf-8"},"/checkout.html":{"body":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>Checkout | Zenzo</title>\n    <link rel=\"stylesheet\" href=\"styles.css?v=zenzo-race-theme-18\">\n  </head>\n  <body class=\"checkout-page\">\n    <main class=\"checkout-shell\">\n      <nav class=\"checkout-nav\" aria-label=\"Checkout navigation\">\n        <a class=\"brand\" href=\"index.html\" aria-label=\"Zenzo home\">\n          <span class=\"brand__logo-frame\"><img src=\"assets/zenzo-logo-mark.png\" alt=\"Zenzo\" class=\"brand__logo\" width=\"520\" height=\"138\"></span>\n        </a>\n        <a class=\"primary-link\" href=\"index.html#catalog\">Back to shop</a>\n      </nav>\n\n      <div class=\"checkout-layout\">\n        <section class=\"checkout-panel\" aria-labelledby=\"checkoutTitle\">\n          <div class=\"checkout-panel__body\">\n            <p class=\"eyebrow\">Checkout</p>\n            <h1 id=\"checkoutTitle\">Shipping and UPI payment</h1>\n            <form class=\"form-grid\" id=\"checkoutForm\">\n              <label class=\"field\">\n                Full name\n                <input name=\"name\" autocomplete=\"name\" required>\n              </label>\n              <label class=\"field\">\n                Email address\n                <input name=\"email\" type=\"email\" autocomplete=\"email\" required>\n              </label>\n              <label class=\"field\">\n                Mobile number\n                <input name=\"phone\" inputmode=\"tel\" autocomplete=\"tel\" required>\n              </label>\n              <label class=\"field field--full\">\n                Delivery address\n                <textarea name=\"address\" autocomplete=\"street-address\" required></textarea>\n              </label>\n              <label class=\"field\">\n                City\n                <input name=\"city\" autocomplete=\"address-level2\" required>\n              </label>\n              <label class=\"field\">\n                State\n                <input name=\"state\" autocomplete=\"address-level1\" required>\n              </label>\n              <label class=\"field\">\n                PIN code\n                <input name=\"pin\" inputmode=\"numeric\" autocomplete=\"postal-code\" required>\n              </label>\n              <div class=\"upi-panel field--full\" aria-label=\"UPI payment instructions\">\n                <strong>Secure UPI checkout</strong>\n                <p>Pay through the secure payment window. UPI is available at checkout and Zenzo confirms paid orders automatically.</p>\n              </div>\n            </form>\n          </div>\n        </section>\n\n        <aside class=\"checkout-panel\" aria-labelledby=\"orderTitle\">\n          <div class=\"checkout-panel__body\">\n            <h2 id=\"orderTitle\">Order summary</h2>\n            <div class=\"order-list\" id=\"orderList\"></div>\n            <div class=\"checkout-total\">\n              <span>Subtotal</span>\n              <strong id=\"checkoutSubtotal\">₹0</strong>\n            </div>\n            <button class=\"place-order\" form=\"checkoutForm\" type=\"submit\">Pay securely</button>\n            <p class=\"checkout-note\" id=\"checkoutNote\">UPI payment is handled through the payment gateway. The UPI ID is not shown to buyers.</p>\n          </div>\n        </aside>\n      </div>\n    </main>\n\n    <script src=\"https://checkout.razorpay.com/v1/checkout.js\"></script>\n    <script src=\"checkout.js?v=zenzo-race-theme-18\"></script>\n  </body>\n</html>\n","type":"text/html; charset=utf-8"},"/admin.html":{"body":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>Admin | Zenzo</title>\n    <link rel=\"stylesheet\" href=\"styles.css?v=zenzo-race-theme-18\">\n  </head>\n  <body class=\"checkout-page\">\n    <main class=\"checkout-shell\">\n      <nav class=\"checkout-nav\" aria-label=\"Admin navigation\">\n        <a class=\"brand\" href=\"index.html\" aria-label=\"Zenzo home\">\n          <span class=\"brand__logo-frame\"><img src=\"assets/zenzo-logo-mark.png\" alt=\"Zenzo\" class=\"brand__logo\" width=\"520\" height=\"138\"></span>\n        </a>\n        <a class=\"primary-link\" href=\"index.html#catalog\">Back to shop</a>\n      </nav>\n\n      <section class=\"checkout-panel admin-login\" id=\"loginPanel\" aria-labelledby=\"loginTitle\">\n        <div class=\"checkout-panel__body\">\n          <p class=\"eyebrow\">Admin</p>\n          <h1 id=\"loginTitle\">Zenzo product login</h1>\n          <form class=\"form-grid\" id=\"loginForm\">\n            <label class=\"field field--full\">\n              Email address\n              <input type=\"email\" name=\"email\" autocomplete=\"username\" required>\n            </label>\n            <label class=\"field field--full\">\n              Password\n              <input type=\"password\" name=\"password\" autocomplete=\"current-password\" required>\n            </label>\n            <button class=\"place-order field--full\" type=\"submit\">Log in</button>\n            <p class=\"checkout-note field--full\" id=\"loginMessage\">Admin email: <strong>zenzo.org@gmail.com</strong></p>\n          </form>\n        </div>\n      </section>\n\n      <div class=\"checkout-layout admin-dashboard\" id=\"adminDashboard\" hidden>\n        <section class=\"checkout-panel\" aria-labelledby=\"productFormTitle\">\n          <div class=\"checkout-panel__body\">\n            <p class=\"eyebrow\">Products</p>\n            <h1 id=\"productFormTitle\">Add new product</h1>\n            <form class=\"form-grid\" id=\"productForm\">\n              <label class=\"field field--full\">\n                Product name\n                <input name=\"name\" required>\n              </label>\n              <label class=\"field\">\n                Collection\n                <select name=\"collection\" required>\n                  <option>Hot Wheels</option>\n                  <option>Figurines</option>\n                  <option>3D collectibles</option>\n                </select>\n              </label>\n              <label class=\"field\">\n                Series\n                <input name=\"series\" value=\"Assorted Hot Wheels\" required>\n              </label>\n              <label class=\"field\">\n                Year\n                <input name=\"year\" inputmode=\"numeric\" value=\"2025\" required>\n              </label>\n              <label class=\"field\">\n                Condition\n                <select name=\"condition\" required>\n                  <option>Sealed Pack</option>\n                  <option>Sealed</option>\n                  <option>Loose</option>\n                  <option>Premium</option>\n                </select>\n              </label>\n              <label class=\"field\">\n                Price in INR\n                <input name=\"price\" inputmode=\"numeric\" required>\n              </label>\n              <label class=\"field\">\n                Stock\n                <input name=\"stock\" inputmode=\"numeric\" value=\"1\" required>\n              </label>\n              <label class=\"field field--full\">\n                Product photo\n                <input name=\"image\" type=\"file\" accept=\"image/*\">\n              </label>\n              <label class=\"field field--full\">\n                Notes\n                <textarea name=\"notes\" required>Sealed Hot Wheels pack photographed from available stock.</textarea>\n              </label>\n              <button class=\"place-order field--full\" type=\"submit\">Add product</button>\n              <p class=\"checkout-note field--full\">Products added here appear in the selected collection after saving.</p>\n            </form>\n          </div>\n        </section>\n\n        <aside class=\"checkout-panel\" aria-labelledby=\"customProductsTitle\">\n          <div class=\"checkout-panel__body\">\n            <h2 id=\"customProductsTitle\">Added products</h2>\n            <div class=\"admin-products\" id=\"adminProducts\"></div>\n            <button class=\"remove-button admin-logout\" id=\"logoutButton\" type=\"button\">Log out</button>\n          </div>\n        </aside>\n      </div>\n    </main>\n\n    <script src=\"admin.js?v=zenzo-race-theme-18\"></script>\n  </body>\n</html>\n","type":"text/html; charset=utf-8"},"/styles.css":{"body":":root {\n  --black: #070b12;\n  --ink: #f7fbff;\n  --muted: #b4c3d4;\n  --line: rgba(255, 255, 255, 0.16);\n  --paper: #07111c;\n  --panel: #111c2a;\n  --surface: #101a27;\n  --surface-warm: #181423;\n  --surface-blue: #0b2034;\n  --white: #ffffff;\n  --accent: #ff3b3b;\n  --blue: #35a8ff;\n  --red: #ff3b3b;\n  --gold: #ffc233;\n  --green: #20c997;\n  --teal: #22d3ee;\n  --shadow: 0 22px 60px rgba(0, 0, 0, 0.42);\n}\n\n* {\n  box-sizing: border-box;\n}\n\n[hidden] {\n  display: none !important;\n}\n\nhtml {\n  scroll-behavior: smooth;\n}\n\nbody {\n  margin: 0;\n  background:\n    radial-gradient(circle at 12% 18%, rgba(255, 59, 59, 0.3), transparent 20%),\n    radial-gradient(circle at 88% 18%, rgba(53, 168, 255, 0.28), transparent 24%),\n    linear-gradient(125deg, rgba(255, 59, 59, 0.28) 0 24%, transparent 24% 49%, rgba(53, 168, 255, 0.24) 49% 74%, transparent 74%),\n    linear-gradient(155deg, #050910 0, #091522 38%, #140b17 68%, #061120 100%);\n  color: var(--ink);\n  font-family: Arial, Helvetica, sans-serif;\n  line-height: 1.5;\n}\n\nmain {\n  position: relative;\n  isolation: isolate;\n  padding-bottom: 1px;\n}\n\nmain::before {\n  content: \"\";\n  position: absolute;\n  inset: -110px 0 0;\n  z-index: -1;\n  background:\n    linear-gradient(112deg, rgba(255, 59, 59, 0.78) 0 11%, transparent 11% 88%, rgba(53, 168, 255, 0.78) 88%),\n    linear-gradient(292deg, transparent 0 8%, rgba(53, 168, 255, 0.56) 8% 18%, transparent 18% 78%, rgba(255, 59, 59, 0.52) 78% 88%, transparent 88%),\n    linear-gradient(180deg, rgba(3, 7, 14, 0.66), rgba(3, 7, 14, 0.18));\n  opacity: 0.92;\n  pointer-events: none;\n}\n\nbutton,\ninput,\nselect {\n  font: inherit;\n}\n\nbutton,\na {\n  -webkit-tap-highlight-color: transparent;\n}\n\n.hero {\n  position: relative;\n  min-height: min(760px, 92vh);\n  display: grid;\n  align-items: center;\n  isolation: isolate;\n  overflow: hidden;\n  background: #111820;\n}\n\n.hero__image,\n.hero__shade {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n}\n\n.hero__image {\n  object-fit: cover;\n  object-position: center;\n  filter: saturate(1.08) contrast(0.92);\n  opacity: 0.64;\n  z-index: -2;\n}\n\n.hero__shade {\n  z-index: -1;\n  background:\n    linear-gradient(120deg, rgba(229, 57, 53, 0.42), rgba(8, 120, 201, 0.32) 48%, rgba(23, 143, 105, 0.32)),\n    linear-gradient(90deg, rgba(9, 17, 28, 0.82), rgba(9, 17, 28, 0.28) 50%, rgba(9, 17, 28, 0.62)),\n    linear-gradient(0deg, rgba(9, 17, 28, 0.7), transparent 52%);\n}\n\n.topbar {\n  position: absolute;\n  inset: 0 0 auto 0;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 16px;\n  padding: 22px clamp(18px, 4vw, 56px);\n}\n\n.topbar__actions {\n  display: inline-flex;\n  align-items: center;\n  gap: 10px;\n}\n\n.brand {\n  display: inline-flex;\n  align-items: center;\n  gap: 10px;\n  color: #fff;\n  text-decoration: none;\n  font-weight: 800;\n}\n\n.brand__logo-frame {\n  display: block;\n  width: 128px;\n  height: 34px;\n  overflow: hidden;\n  border-radius: 3px;\n  background: transparent;\n}\n\n.brand__logo {\n  width: 100%;\n  height: 100%;\n  object-fit: contain;\n  display: block;\n}\n\n.cart-button,\n.primary-link,\n.checkout-link,\n.admin-link,\n.footer-admin-link,\n.details-link {\n  border: 0;\n  border-radius: 6px;\n  cursor: pointer;\n  font-weight: 800;\n  text-decoration: none;\n}\n\n.cart-button {\n  display: inline-flex;\n  align-items: center;\n  gap: 10px;\n  padding: 10px 14px;\n  color: var(--ink);\n  background: rgba(255, 255, 255, 0.14);\n  border: 1px solid rgba(255, 255, 255, 0.22);\n  box-shadow: 0 12px 28px rgba(4, 20, 38, 0.24);\n}\n\n.admin-link {\n  min-height: 42px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  padding: 9px 12px;\n  color: var(--white);\n  border: 1px solid rgba(255, 255, 255, 0.55);\n}\n\n.cart-button__count {\n  display: grid;\n  min-width: 24px;\n  height: 24px;\n  place-items: center;\n  border-radius: 999px;\n  color: #fff;\n  background: var(--red);\n  font-size: 0.82rem;\n}\n\n.hero__content {\n  width: min(1180px, calc(100% - 36px));\n  margin: 54px auto 92px;\n  color: #fff;\n  text-align: center;\n  display: grid;\n  justify-items: center;\n  gap: 20px;\n}\n\n.eyebrow {\n  margin: 0 0 10px;\n  color: var(--gold);\n  font-size: 0.82rem;\n  font-weight: 900;\n  letter-spacing: 0;\n  text-transform: uppercase;\n}\n\nh1,\nh2,\nh3,\np {\n  overflow-wrap: anywhere;\n}\n\n.hero h1 {\n  margin: 0;\n  max-width: none;\n  font-family: \"Brush Script MT\", \"Segoe Print\", \"Trebuchet MS\", Arial, sans-serif;\n  font-size: clamp(3.2rem, 8vw, 7rem);\n  line-height: 0.86;\n  letter-spacing: 0;\n  text-shadow: 0 16px 34px rgba(0, 0, 0, 0.46);\n}\n\n.hero__copy {\n  max-width: 760px;\n  margin: 2px auto 0;\n  color: rgba(255, 255, 255, 0.9);\n  font-size: 1.15rem;\n}\n\n.hero__tagline {\n  margin: -8px 0 8px;\n  color: var(--gold);\n  font-size: 0.98rem;\n  font-weight: 900;\n}\n\n.hero__headline {\n  position: relative;\n  display: grid;\n  justify-items: center;\n  gap: 0;\n  overflow: visible;\n  padding: 8px 0 8px;\n}\n\n.hero__line {\n  display: block;\n  white-space: nowrap;\n  animation: hero-slide-in 780ms cubic-bezier(0.16, 1, 0.3, 1) both;\n}\n\n.hero__line--primary {\n  color: #ffffff;\n  font-size: 0.72em;\n  font-weight: 800;\n  text-transform: none;\n}\n\n.hero__line--accent {\n  color: transparent;\n  background: linear-gradient(92deg, #ff3b3b, #ffffff 44%, #35a8ff 82%);\n  background-clip: text;\n  -webkit-background-clip: text;\n  font-size: 1.08em;\n  font-weight: 800;\n  animation-delay: 130ms;\n}\n\n.hero__motion {\n  position: relative;\n  z-index: 0;\n  width: min(760px, 84vw);\n  height: 26px;\n  overflow: hidden;\n  margin: -4px 0 2px;\n  transform: skewX(-16deg);\n}\n\n.hero__motion span {\n  position: absolute;\n  inset: auto auto 9px 0;\n  width: 38%;\n  height: 5px;\n  border-radius: 999px;\n  background: linear-gradient(90deg, transparent, rgba(255, 59, 59, 0.96), #ffffff, rgba(53, 168, 255, 0.96), transparent);\n  box-shadow: 0 0 22px rgba(53, 168, 255, 0.36);\n  animation: race-streak 2.6s linear infinite;\n}\n\n.hero__motion span:nth-child(2) {\n  bottom: 2px;\n  width: 26%;\n  animation-delay: 540ms;\n  opacity: 0.72;\n}\n\n.hero__motion span:nth-child(3) {\n  bottom: 17px;\n  width: 18%;\n  animation-delay: 1.18s;\n  opacity: 0.62;\n}\n\n.primary-link,\n.checkout-link {\n  position: relative;\n  z-index: 2;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  min-height: 46px;\n  padding: 12px 18px;\n  color: #ffffff !important;\n  background: #ff3b3b;\n  border: 1px solid rgba(255, 255, 255, 0.78);\n  box-shadow: 0 14px 30px rgba(0, 0, 0, 0.34), 0 12px 26px rgba(255, 59, 59, 0.24);\n  text-shadow: none;\n}\n\n.hero .primary-link {\n  min-width: 238px;\n  color: #ffffff !important;\n  background: linear-gradient(180deg, #ff4b3f 0%, #e3292e 100%);\n  border: 1px solid rgba(255, 255, 255, 0.72);\n  box-shadow: 0 16px 32px rgba(0, 0, 0, 0.32), 0 0 22px rgba(255, 59, 59, 0.2);\n}\n\n.showcase {\n  width: min(1180px, calc(100% - 32px));\n  margin: -64px auto 34px;\n  position: relative;\n  z-index: 2;\n  display: grid;\n  grid-template-columns: minmax(260px, 0.8fr) minmax(0, 1.2fr);\n  gap: 18px;\n  align-items: stretch;\n  padding: 14px;\n  border: 1px solid rgba(255, 255, 255, 0.2);\n  border-radius: 10px;\n  background: linear-gradient(135deg, rgba(255, 59, 59, 0.24), rgba(53, 168, 255, 0.18), rgba(5, 9, 16, 0.82));\n  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.4);\n}\n\n.showcase__copy {\n  display: grid;\n  align-content: center;\n  gap: 10px;\n  padding: clamp(18px, 3vw, 34px);\n  border-radius: 8px;\n  color: #ffffff;\n  background: linear-gradient(135deg, #111827, #0b3557);\n}\n\n.showcase__copy h2,\n.showcase__copy p {\n  margin: 0;\n}\n\n.showcase__copy h2 {\n  font-size: clamp(1.75rem, 3vw, 3rem);\n  line-height: 1.03;\n}\n\n.showcase__copy p:not(.eyebrow) {\n  color: rgba(255, 255, 255, 0.86);\n}\n\n.showcase img {\n  width: 100%;\n  height: 100%;\n  min-height: 280px;\n  object-fit: cover;\n  border-radius: 8px;\n  display: block;\n}\n\n.collections {\n  width: min(1180px, calc(100% - 32px));\n  margin: 24px auto 0;\n  display: grid;\n  grid-template-columns: auto minmax(0, 1fr);\n  gap: 14px;\n  align-items: center;\n  padding: 12px;\n  border: 1px solid rgba(255, 255, 255, 0.14);\n  border-radius: 10px;\n  background:\n    linear-gradient(135deg, rgba(255, 59, 59, 0.16), rgba(53, 168, 255, 0.12)),\n    rgba(16, 26, 39, 0.82);\n  box-shadow: 0 16px 38px rgba(0, 0, 0, 0.24);\n}\n\n.collections__intro {\n  display: grid;\n  align-content: center;\n  gap: 4px;\n  padding: 6px 8px;\n}\n\n.collections h2 {\n  margin: 0;\n  color: #ffffff;\n  font-size: clamp(1.18rem, 2vw, 1.55rem);\n  line-height: 1.05;\n}\n\n.collections__intro p:not(.eyebrow) {\n  margin: 0;\n  color: rgba(255, 255, 255, 0.82);\n  font-size: 1rem;\n}\n\n.collection-list {\n  display: grid;\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n  gap: 8px;\n}\n\n.collection-card {\n  position: relative;\n  min-height: 54px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  overflow: hidden;\n  padding: 10px 12px;\n  border: 1px solid rgba(255, 255, 255, 0.16);\n  border-radius: 8px;\n  color: var(--ink);\n  background:\n    linear-gradient(135deg, rgba(255, 59, 59, 0.12), rgba(53, 168, 255, 0.1)),\n    rgba(16, 26, 39, 0.92);\n  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.22);\n  cursor: pointer;\n  text-align: left;\n  transition: transform 160ms ease, border-color 160ms ease, box-shadow 160ms ease;\n}\n\n.collection-card::before {\n  content: \"\";\n  position: absolute;\n  inset: auto -24px -44px auto;\n  width: 86px;\n  height: 86px;\n  border-radius: 50%;\n  background: rgba(255, 255, 255, 0.1);\n}\n\n.collection-card::after {\n  content: \"\";\n  position: absolute;\n  inset: 0;\n  border-radius: inherit;\n  background: linear-gradient(135deg, rgba(255, 255, 255, 0.12), transparent 42%);\n  opacity: 0;\n  transition: opacity 160ms ease;\n}\n\n.collection-card:hover {\n  transform: translateY(-3px);\n  border-color: rgba(255, 255, 255, 0.3);\n  box-shadow: 0 22px 48px rgba(0, 0, 0, 0.34);\n}\n\n.collection-card:hover::after,\n.collection-card.is-active::after {\n  opacity: 1;\n}\n\n.collection-card__icon {\n  position: relative;\n  z-index: 1;\n  display: inline-grid;\n  width: 38px;\n  height: 38px;\n  place-items: center;\n  border-radius: 50%;\n  color: #ffffff;\n  background: rgba(255, 255, 255, 0.12);\n  font-size: 0.82rem;\n  font-weight: 900;\n}\n\n.collection-card strong {\n  position: relative;\n  z-index: 1;\n  font-size: 0.98rem;\n  line-height: 1.08;\n  text-align: center;\n}\n\n.collection-card span {\n  position: relative;\n  z-index: 1;\n  color: var(--muted);\n  font-size: 0.92rem;\n}\n\n.collection-card--hotwheels {\n  background:\n    linear-gradient(135deg, rgba(255, 59, 59, 0.32), rgba(53, 168, 255, 0.1)),\n    rgba(16, 26, 39, 0.94);\n}\n\n.collection-card--figurines {\n  background:\n    linear-gradient(135deg, rgba(255, 194, 51, 0.24), rgba(255, 59, 59, 0.08)),\n    rgba(16, 26, 39, 0.94);\n}\n\n.collection-card--printed {\n  background:\n    linear-gradient(135deg, rgba(34, 211, 238, 0.26), rgba(53, 168, 255, 0.12)),\n    rgba(16, 26, 39, 0.94);\n}\n\n.collection-card.is-active {\n  border-color: rgba(255, 255, 255, 0.36);\n  background:\n    linear-gradient(135deg, rgba(255, 59, 59, 0.62), rgba(53, 168, 255, 0.46)),\n    rgba(16, 26, 39, 0.96);\n}\n\n.collection-card.is-active span {\n  color: rgba(255, 255, 255, 0.86);\n}\n\n.toolbar {\n  width: min(1180px, calc(100% - 32px));\n  margin: 34px auto 0;\n  display: grid;\n  grid-template-columns: minmax(220px, 1fr) auto auto;\n  gap: 14px;\n  align-items: center;\n  padding: 14px;\n  border: 1px solid rgba(255, 255, 255, 0.18);\n  border-radius: 10px;\n  background: linear-gradient(135deg, rgba(255, 59, 59, 0.18), rgba(53, 168, 255, 0.16), rgba(16, 26, 39, 0.88));\n  box-shadow: 0 18px 42px rgba(0, 0, 0, 0.24);\n}\n\n.search input,\n.select-label select {\n  width: 100%;\n  min-height: 44px;\n  border: 1px solid var(--line);\n  border-radius: 6px;\n  background: linear-gradient(180deg, #142338, var(--surface-blue));\n  color: var(--ink);\n  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.18);\n}\n\n.search input {\n  padding: 0 14px;\n}\n\n.select-label select {\n  padding: 0 34px 0 12px;\n}\n\n.filter-group {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n}\n\n.chip {\n  min-height: 40px;\n  padding: 8px 13px;\n  border: 1px solid var(--line);\n  border-radius: 999px;\n  background: rgba(255, 255, 255, 0.08);\n  color: var(--ink);\n  cursor: pointer;\n}\n\n.chip.is-active {\n  border-color: rgba(255, 255, 255, 0.28);\n  color: var(--white);\n  background: linear-gradient(135deg, var(--red), var(--blue));\n}\n\n.catalog {\n  width: min(1180px, calc(100% - 32px));\n  margin: 28px auto 64px;\n  padding: 18px;\n  border-radius: 12px;\n  border: 1px solid rgba(255, 255, 255, 0.1);\n  background: linear-gradient(135deg, rgba(53, 168, 255, 0.16), rgba(255, 59, 59, 0.12), rgba(7, 11, 18, 0.64));\n  box-shadow: 0 24px 58px rgba(0, 0, 0, 0.28);\n}\n\n.section-heading {\n  display: flex;\n  justify-content: space-between;\n  align-items: end;\n  gap: 20px;\n  margin-bottom: 18px;\n}\n\n.section-heading h2 {\n  margin: 0;\n  font-size: 2.4rem;\n  line-height: 1.05;\n  color: #ffffff;\n  text-shadow: 0 3px 14px rgba(9, 17, 28, 0.24);\n}\n\n.section-heading .eyebrow {\n  color: #ffffff;\n  text-shadow: 0 3px 12px rgba(9, 17, 28, 0.22);\n}\n\n.product-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));\n  gap: 18px;\n}\n\n.product-card {\n  display: grid;\n  grid-template-rows: auto 1fr;\n  min-width: 0;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  overflow: hidden;\n  background: linear-gradient(180deg, rgba(16, 26, 39, 0.96), rgba(24, 20, 35, 0.96));\n  box-shadow: 0 18px 44px rgba(0, 0, 0, 0.3);\n  cursor: pointer;\n  transition: transform 160ms ease, box-shadow 160ms ease, border-color 160ms ease;\n}\n\n.product-card:hover {\n  transform: translateY(-3px);\n  border-color: rgba(53, 168, 255, 0.46);\n  box-shadow: 0 24px 56px rgba(0, 0, 0, 0.4);\n}\n\n.product-media {\n  position: relative;\n  height: 260px;\n  display: grid;\n  place-items: center;\n  overflow: hidden;\n  background:\n    radial-gradient(circle at 18% 14%, rgba(255, 59, 59, 0.18), transparent 36%),\n    radial-gradient(circle at 82% 18%, rgba(53, 168, 255, 0.2), transparent 38%),\n    linear-gradient(135deg, rgba(255, 255, 255, 0.06), rgba(53, 168, 255, 0.08)),\n    #0c1522;\n}\n\n.product-link {\n  color: inherit;\n  text-decoration: none;\n}\n\n.product-media::before {\n  content: \"\";\n  position: absolute;\n  inset: auto 18px 26px;\n  height: 14px;\n  border-radius: 999px;\n  background: rgba(255, 255, 255, 0.16);\n  filter: blur(7px);\n}\n\n.product-photo {\n  position: relative;\n  z-index: 1;\n  width: 82%;\n  height: 220px;\n  object-fit: contain;\n}\n\n.photo-fallback {\n  position: relative;\n  z-index: 1;\n  padding: 10px 14px;\n  border: 1px solid var(--line);\n  border-radius: 6px;\n  color: var(--muted);\n  background: rgba(16, 26, 39, 0.92);\n  font-weight: 800;\n}\n\n.toy-car {\n  position: relative;\n  width: min(260px, 78%);\n  aspect-ratio: 3.1 / 1;\n  transform: rotate(-3deg);\n  filter: drop-shadow(0 16px 16px rgba(0, 0, 0, 0.24));\n}\n\n.toy-car::before,\n.toy-car::after {\n  content: \"\";\n  position: absolute;\n}\n\n.toy-car__body {\n  position: absolute;\n  inset: 28% 4% 22%;\n  border-radius: 28px 48px 20px 18px;\n  background:\n    linear-gradient(90deg, rgba(255,255,255,0.32), transparent 18% 70%, rgba(0,0,0,0.16)),\n    var(--car);\n}\n\n.toy-car__roof {\n  position: absolute;\n  left: 30%;\n  top: 4%;\n  width: 35%;\n  height: 38%;\n  border-radius: 26px 28px 6px 6px;\n  background:\n    linear-gradient(135deg, rgba(255,255,255,0.8), rgba(255,255,255,0.12)),\n    var(--glass);\n}\n\n.toy-car__stripe {\n  position: absolute;\n  left: 13%;\n  right: 18%;\n  top: 43%;\n  height: 8%;\n  border-radius: 999px;\n  background: rgba(255, 255, 255, 0.78);\n}\n\n.toy-car__wheel {\n  position: absolute;\n  bottom: 8%;\n  width: 24%;\n  aspect-ratio: 1;\n  border: 8px solid #171717;\n  border-radius: 50%;\n  background: radial-gradient(circle, #d7d1c7 0 26%, #777 27% 35%, #262626 36%);\n}\n\n.toy-car__wheel:first-of-type {\n  left: 15%;\n}\n\n.toy-car__wheel:last-of-type {\n  right: 13%;\n}\n\n.product-info {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  padding: 16px;\n}\n\n.product-topline {\n  display: flex;\n  justify-content: space-between;\n  gap: 12px;\n  align-items: start;\n}\n\n.product-title-link {\n  color: var(--ink);\n  text-decoration: none;\n}\n\n.product-title-link:hover h3,\n.details-link:hover,\n.footer-admin-link:hover {\n  text-decoration: underline;\n}\n\n.product-card h3 {\n  margin: 0;\n  font-size: 1.08rem;\n  line-height: 1.2;\n}\n\n.price {\n  color: var(--blue);\n  font-weight: 900;\n  white-space: nowrap;\n}\n\n.meta {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 7px;\n  margin: 0;\n}\n\n.meta span {\n  padding: 4px 8px;\n  border-radius: 999px;\n  border: 1px solid rgba(255, 255, 255, 0.1);\n  background: rgba(53, 168, 255, 0.14);\n  color: #dcefff;\n  font-size: 0.82rem;\n  font-weight: 700;\n}\n\n.notes {\n  margin: 0;\n  color: var(--muted);\n  font-size: 0.94rem;\n}\n\n.details-link {\n  justify-self: start;\n  color: var(--blue);\n  font-size: 0.94rem;\n}\n\n.add-button {\n  margin-top: auto;\n  min-height: 42px;\n  border: 0;\n  border-radius: 6px;\n  color: #fff;\n  background: linear-gradient(135deg, var(--red), #f06b2f);\n  font-weight: 800;\n  cursor: pointer;\n  box-shadow: 0 10px 22px rgba(229, 57, 53, 0.2);\n}\n\n.add-button:disabled {\n  background: #8f8981;\n  cursor: not-allowed;\n}\n\n.cart-panel {\n  position: fixed;\n  z-index: 30;\n  inset: 0 0 0 auto;\n  width: min(420px, 100%);\n  display: grid;\n  grid-template-rows: auto 1fr auto;\n  background: linear-gradient(180deg, #0a1422, #151020);\n  box-shadow: var(--shadow);\n  transform: translateX(105%);\n  transition: transform 180ms ease;\n}\n\n.cart-panel.is-open {\n  transform: translateX(0);\n}\n\n.cart-panel__header,\n.cart-summary {\n  padding: 18px;\n  border-bottom: 1px solid var(--line);\n}\n\n.cart-panel__header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n\n.cart-panel__header h2 {\n  margin: 0;\n  font-size: 1.3rem;\n}\n\n.icon-button {\n  width: 38px;\n  height: 38px;\n  border: 1px solid var(--line);\n  border-radius: 50%;\n  color: var(--ink);\n  background: rgba(255, 255, 255, 0.08);\n  cursor: pointer;\n}\n\n.cart-items {\n  overflow: auto;\n  padding: 8px 18px;\n}\n\n.cart-item {\n  display: grid;\n  grid-template-columns: 1fr auto;\n  gap: 8px 12px;\n  padding: 14px 0;\n  border-bottom: 1px solid var(--line);\n}\n\n.cart-item h3,\n.cart-item p {\n  margin: 0;\n}\n\n.cart-item p {\n  color: var(--muted);\n  font-size: 0.9rem;\n}\n\n.remove-button {\n  border: 0;\n  color: var(--red);\n  background: transparent;\n  cursor: pointer;\n  font-weight: 800;\n}\n\n.cart-summary {\n  display: grid;\n  gap: 12px;\n  border-top: 1px solid var(--line);\n  border-bottom: 0;\n  background: linear-gradient(180deg, rgba(16, 26, 39, 0.96), rgba(24, 20, 35, 0.96));\n}\n\n.cart-summary__row {\n  display: flex;\n  justify-content: space-between;\n  gap: 16px;\n  font-size: 1.1rem;\n}\n\n.cart-summary p {\n  margin: 0;\n  color: var(--muted);\n  font-size: 0.92rem;\n}\n\n.checkout-link {\n  width: 100%;\n}\n\n.checkout-page {\n  min-height: 100vh;\n  background:\n    radial-gradient(circle at 12% 18%, rgba(255, 59, 59, 0.28), transparent 20%),\n    radial-gradient(circle at 88% 18%, rgba(53, 168, 255, 0.26), transparent 24%),\n    linear-gradient(125deg, rgba(255, 59, 59, 0.24) 0 24%, transparent 24% 49%, rgba(53, 168, 255, 0.22) 49% 74%, transparent 74%),\n    linear-gradient(155deg, #050910 0, #091522 38%, #140b17 68%, #061120 100%);\n}\n\n.product-page .checkout-shell {\n  width: min(1180px, calc(100% - 32px));\n}\n\n.checkout-shell {\n  width: min(1080px, calc(100% - 32px));\n  margin: 0 auto;\n  padding: 28px 0 56px;\n}\n\n.checkout-nav {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 16px;\n  margin-bottom: 28px;\n}\n\n.checkout-nav .brand {\n  color: var(--ink);\n}\n\n.checkout-layout {\n  display: grid;\n  grid-template-columns: minmax(0, 1.35fr) minmax(300px, 0.75fr);\n  gap: 22px;\n  align-items: start;\n}\n\n.checkout-panel {\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: linear-gradient(180deg, rgba(16, 26, 39, 0.96), rgba(24, 20, 35, 0.96));\n  overflow: hidden;\n  box-shadow: 0 18px 44px rgba(0, 0, 0, 0.3);\n}\n\n.checkout-panel__body {\n  display: grid;\n  gap: 16px;\n  padding: 18px;\n}\n\n.checkout-panel h1,\n.checkout-panel h2 {\n  margin: 0;\n}\n\n.checkout-panel h1 {\n  font-size: 2.35rem;\n  line-height: 1.08;\n}\n\n.form-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 14px;\n}\n\n.field {\n  display: grid;\n  gap: 6px;\n  color: var(--muted);\n  font-weight: 700;\n}\n\n.field--full {\n  grid-column: 1 / -1;\n}\n\n.field input,\n.field textarea,\n.field select {\n  width: 100%;\n  min-height: 44px;\n  border: 1px solid var(--line);\n  border-radius: 6px;\n  padding: 10px 12px;\n  color: var(--ink);\n  background: #0d1827;\n}\n\n.field input:focus,\n.field textarea:focus,\n.field select:focus,\n.search input:focus,\n.select-label select:focus {\n  outline: 2px solid rgba(8, 120, 201, 0.28);\n  border-color: var(--blue);\n}\n\n.field textarea {\n  min-height: 96px;\n  resize: vertical;\n}\n\n.upi-panel {\n  display: grid;\n  gap: 8px;\n  padding: 16px;\n  border: 1px solid rgba(53, 168, 255, 0.28);\n  border-radius: 8px;\n  background: linear-gradient(135deg, rgba(53, 168, 255, 0.12), rgba(255, 59, 59, 0.08), rgba(16, 26, 39, 0.9));\n  color: var(--ink);\n}\n\n.upi-panel strong {\n  font-size: 1.05rem;\n}\n\n.upi-panel p {\n  margin: 0;\n  color: var(--muted);\n}\n\n.upi-panel a {\n  color: var(--white);\n  font-weight: 900;\n}\n\n.upi-id {\n  display: inline-flex;\n  width: fit-content;\n  max-width: 100%;\n  padding: 8px 10px;\n  border: 1px solid var(--line);\n  border-radius: 6px;\n  background: #0d1827;\n  color: var(--ink);\n  font-family: Arial, Helvetica, sans-serif;\n  font-size: 1rem;\n  font-weight: 900;\n  overflow-wrap: anywhere;\n}\n\n.payment-options {\n  display: grid;\n  gap: 10px;\n}\n\n.payment-option {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  min-height: 46px;\n  padding: 10px 12px;\n  border: 1px solid var(--line);\n  border-radius: 6px;\n  background: rgba(255, 255, 255, 0.06);\n  font-weight: 800;\n}\n\n.order-list {\n  display: grid;\n  gap: 12px;\n}\n\n.order-line {\n  display: grid;\n  grid-template-columns: 1fr auto;\n  gap: 8px;\n  padding-bottom: 12px;\n  border-bottom: 1px solid var(--line);\n}\n\n.order-line h3,\n.order-line p {\n  margin: 0;\n}\n\n.order-line p {\n  color: var(--muted);\n  font-size: 0.92rem;\n}\n\n.checkout-total {\n  display: flex;\n  justify-content: space-between;\n  gap: 16px;\n  font-size: 1.15rem;\n}\n\n.place-order {\n  width: 100%;\n  min-height: 46px;\n  border: 0;\n  border-radius: 6px;\n  color: #fff;\n  background: linear-gradient(135deg, var(--green), #22b8cf);\n  font-weight: 900;\n  cursor: pointer;\n  box-shadow: 0 10px 22px rgba(23, 143, 105, 0.2);\n}\n\n.checkout-note {\n  margin: 0;\n  color: var(--muted);\n  font-size: 0.92rem;\n}\n\n.product-detail {\n  display: grid;\n  grid-template-columns: minmax(0, 1.05fr) minmax(320px, 0.95fr);\n  gap: 24px;\n  align-items: start;\n}\n\n.product-detail__media,\n.product-detail__info {\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: linear-gradient(180deg, rgba(16, 26, 39, 0.96), rgba(24, 20, 35, 0.96));\n  box-shadow: 0 18px 44px rgba(0, 0, 0, 0.3);\n}\n\n.product-detail__media {\n  min-height: 560px;\n  display: grid;\n  place-items: center;\n  padding: clamp(18px, 4vw, 42px);\n}\n\n.product-detail__media img {\n  width: 100%;\n  max-height: 520px;\n  object-fit: contain;\n}\n\n.product-detail__info {\n  display: grid;\n  gap: 16px;\n  padding: clamp(18px, 3vw, 28px);\n}\n\n.product-detail__info h1 {\n  margin: 0;\n  font-size: clamp(2rem, 4vw, 3.8rem);\n  line-height: 1.02;\n}\n\n.product-detail__price {\n  font-size: 1.8rem;\n}\n\n.detail-block {\n  display: grid;\n  gap: 8px;\n  padding-top: 16px;\n  border-top: 1px solid var(--line);\n}\n\n.detail-block h2,\n.detail-block p {\n  margin: 0;\n}\n\n.detail-block h2 {\n  font-size: 1rem;\n}\n\n.detail-block p {\n  color: var(--muted);\n}\n\n.product-detail__actions {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 10px;\n}\n\n.admin-login {\n  max-width: 560px;\n  margin: 0 auto;\n}\n\n.admin-products {\n  display: grid;\n  gap: 12px;\n}\n\n.admin-product {\n  display: grid;\n  grid-template-columns: 72px 1fr auto;\n  gap: 12px;\n  align-items: center;\n  padding-bottom: 12px;\n  border-bottom: 1px solid var(--line);\n}\n\n.admin-product img {\n  width: 72px;\n  height: 72px;\n  object-fit: cover;\n  border-radius: 6px;\n  background: var(--surface-blue);\n}\n\n.admin-product h3,\n.admin-product p {\n  margin: 0;\n}\n\n.admin-product p {\n  color: var(--muted);\n  font-size: 0.9rem;\n}\n\n.admin-logout {\n  justify-self: start;\n}\n\n.scrim {\n  position: fixed;\n  z-index: 20;\n  inset: 0;\n  background: rgba(0, 0, 0, 0.38);\n}\n\n.empty-state {\n  padding: 28px;\n  border: 1px dashed rgba(53, 168, 255, 0.42);\n  border-radius: 8px;\n  color: var(--muted);\n  background: linear-gradient(180deg, rgba(16, 26, 39, 0.92), rgba(24, 20, 35, 0.92));\n  text-align: center;\n}\n\nfooter {\n  padding: 28px 18px;\n  border-top: 1px solid rgba(53, 168, 255, 0.18);\n  color: #dbeafe;\n  background: linear-gradient(135deg, #070b12, #0b2034);\n  text-align: center;\n}\n\nfooter p {\n  margin: 0;\n}\n\n.footer-admin-link {\n  display: inline-flex;\n  margin-top: 10px;\n  color: var(--gold);\n  font-size: 0.82rem;\n}\n\n.sr-only {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  padding: 0;\n  margin: -1px;\n  overflow: hidden;\n  clip: rect(0, 0, 0, 0);\n  white-space: nowrap;\n  border: 0;\n}\n\n@keyframes hero-slide-in {\n  from {\n    opacity: 0;\n    transform: translateY(38px) scale(0.96);\n    filter: blur(8px);\n  }\n\n  to {\n    opacity: 1;\n    transform: translateY(0) scale(1);\n    filter: blur(0);\n  }\n}\n\n@keyframes race-streak {\n  from {\n    transform: translateX(-125%);\n  }\n\n  to {\n    transform: translateX(330%);\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .hero__line,\n  .hero__motion span {\n    animation: none;\n  }\n}\n\n@media (max-width: 900px) {\n  .hero h1 {\n    font-size: clamp(2.7rem, 10vw, 4.6rem);\n  }\n\n  .showcase {\n    grid-template-columns: 1fr;\n    margin-top: -44px;\n  }\n\n  .showcase img {\n    min-height: 240px;\n  }\n\n  .section-heading h2 {\n    font-size: 2rem;\n  }\n\n  .collections {\n    grid-template-columns: 1fr;\n  }\n\n  .collection-list {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n\n  .toolbar {\n    grid-template-columns: 1fr auto;\n    align-items: start;\n  }\n\n  .search {\n    grid-column: 1 / -1;\n  }\n\n  .product-grid {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n\n  .checkout-layout {\n    grid-template-columns: 1fr;\n  }\n\n  .product-detail {\n    grid-template-columns: 1fr;\n  }\n\n  .product-detail__media {\n    min-height: 420px;\n  }\n}\n\n@media (max-width: 640px) {\n  .hero {\n    min-height: 620px;\n  }\n\n  .topbar {\n    padding: 16px;\n  }\n\n  .brand__logo-frame {\n    width: 108px;\n    height: 34px;\n  }\n\n  .hero__content {\n    width: calc(100% - 32px);\n    margin: 64px 16px 86px;\n  }\n\n  .cart-button {\n    min-height: 42px;\n    padding: 9px 12px;\n  }\n\n  .admin-link {\n    min-height: 42px;\n    padding: 9px 10px;\n  }\n\n  .hero h1 {\n    max-width: none;\n    font-size: clamp(2.35rem, 13vw, 3.8rem);\n  }\n\n  .hero__copy {\n    font-size: 1rem;\n  }\n\n  .hero__motion {\n    width: min(520px, 86vw);\n    height: 22px;\n  }\n\n  .showcase {\n    width: min(100% - 24px, 1180px);\n    padding: 10px;\n  }\n\n  .showcase__copy {\n    padding: 18px;\n  }\n\n  .showcase img {\n    min-height: 210px;\n  }\n\n  .section-heading h2 {\n    font-size: 1.65rem;\n  }\n\n  .toolbar,\n  .collections,\n  .catalog,\n  .checkout-shell {\n    width: min(100% - 24px, 1180px);\n  }\n\n  .toolbar {\n    margin-top: 22px;\n    grid-template-columns: 1fr;\n    gap: 10px;\n  }\n\n  .filter-group {\n    display: grid;\n    grid-template-columns: repeat(3, minmax(0, 1fr));\n    gap: 6px;\n  }\n\n  .collection-list {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n\n  .collection-card {\n    min-height: 48px;\n    padding: 9px 8px;\n  }\n\n  .chip {\n    width: 100%;\n    min-height: 38px;\n    padding: 7px 8px;\n    font-size: 0.92rem;\n  }\n\n  .section-heading {\n    display: block;\n    margin-bottom: 14px;\n  }\n\n  .product-grid {\n    grid-template-columns: 1fr;\n    gap: 14px;\n  }\n\n  .product-media {\n    height: 220px;\n  }\n\n  .product-photo {\n    height: 188px;\n  }\n\n  .product-info {\n    padding: 14px;\n  }\n\n  .product-topline {\n    display: grid;\n    grid-template-columns: 1fr auto;\n    gap: 8px;\n  }\n\n  .price {\n    font-size: 1rem;\n  }\n\n  .notes {\n    font-size: 0.92rem;\n  }\n\n  .add-button {\n    min-height: 48px;\n  }\n\n  .product-detail__media {\n    min-height: 320px;\n  }\n\n  .product-detail__media img {\n    max-height: 310px;\n  }\n\n  .product-detail__actions {\n    grid-template-columns: 1fr;\n  }\n\n  .form-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .checkout-shell {\n    padding: 18px 0 36px;\n  }\n\n  .checkout-nav {\n    margin-bottom: 18px;\n  }\n\n  .checkout-nav .primary-link {\n    min-height: 40px;\n    padding: 9px 12px;\n    font-size: 0.92rem;\n  }\n\n  .checkout-panel__body {\n    padding: 14px;\n  }\n\n  .checkout-panel h1 {\n    font-size: 1.85rem;\n  }\n\n  .order-line {\n    grid-template-columns: 1fr;\n  }\n\n  .admin-product {\n    grid-template-columns: 58px 1fr;\n  }\n\n  .admin-product .remove-button {\n    grid-column: 2;\n    justify-self: start;\n  }\n}\n\n@media (max-width: 390px) {\n  .hero h1 {\n    font-size: 2.15rem;\n  }\n\n  .filter-group {\n    grid-template-columns: 1fr;\n  }\n\n  .brand__logo-frame {\n    width: 96px;\n    height: 32px;\n  }\n}\n","type":"text/css; charset=utf-8"},"/app.js":{"body":"const baseInventory = [\n  {\n    id: \"f1-race-team-5-pack\",\n    name: \"Hot Wheels Formula 1 Race Team 5-Pack\",\n    series: \"Formula 1 Collection\",\n    year: 2025,\n    condition: \"Sealed Pack\",\n    price: 1499,\n    stock: 7,\n    image: \"assets/catalog/f1-5-pack.jpg\",\n    imageAlt: \"Hot Wheels Formula 1 Race Team 5-Pack in retail packaging\",\n    color: \"#e1262f\",\n    bg: \"#e7edf2\",\n    glass: \"#b9dfee\",\n    notes: \"Set of 5 Formula 1-themed 1:64 die-cast race cars. New carded packs; 7 available.\"\n  },\n  {\n    id: \"mystery-models-foil-pack\",\n    name: \"Hot Wheels Mystery Models Foil Pack\",\n    series: \"Mystery Models\",\n    year: 2025,\n    condition: \"Sealed\",\n    price: 249,\n    stock: 25,\n    image: \"assets/catalog/mystery-models.jpg\",\n    imageAlt: \"Hot Wheels Mystery Models sealed foil pack\",\n    color: \"#0b8ec9\",\n    bg: \"#dceef8\",\n    glass: \"#b9dfee\",\n    notes: \"Sealed surprise pack with one 1:64 Hot Wheels vehicle and matching sticker inside. 25 available.\"\n  },\n  {\n    id: \"assorted-2-pack-blue-orange\",\n    name: \"Hot Wheels Blue & Orange Sealed 2-Pack\",\n    series: \"Assorted Hot Wheels\",\n    year: 2025,\n    condition: \"Sealed Pack\",\n    price: 899,\n    stock: 1,\n    image: \"assets/catalog/blue-orange-2-pack.jpg\",\n    imageAlt: \"Two sealed Hot Wheels packs with blue and orange cars\",\n    color: \"#242424\",\n    bg: \"#f8f7f3\",\n    glass: \"#ffffff\",\n    notes: \"Two sealed Hot Wheels packs photographed from the actual available stock.\"\n  },\n  {\n    id: \"assorted-3-pack-sports-cars\",\n    name: \"Hot Wheels Sports Car Sealed 3-Pack\",\n    series: \"Assorted Hot Wheels\",\n    year: 2025,\n    condition: \"Sealed Pack\",\n    price: 1199,\n    stock: 1,\n    image: \"assets/catalog/sports-car-3-pack.jpg\",\n    imageAlt: \"Three sealed Hot Wheels sports car packs\",\n    color: \"#242424\",\n    bg: \"#f8f7f3\",\n    glass: \"#ffffff\",\n    notes: \"Three sealed Hot Wheels packs photographed from the actual available stock.\"\n  },\n  {\n    id: \"classic-black-racer\",\n    name: \"Hot Wheels Classic Black Racer\",\n    series: \"Vintage Racing Club\",\n    year: 2025,\n    condition: \"Sealed Pack\",\n    price: 699,\n    stock: 1,\n    image: \"assets/catalog/classic-black-racer.jpg\",\n    imageAlt: \"Sealed Hot Wheels classic black race car\",\n    color: \"#242424\",\n    bg: \"#f8f7f3\",\n    glass: \"#ffffff\",\n    notes: \"Single sealed Hot Wheels pack with actual product photo.\"\n  },\n  {\n    id: \"classic-red-racer\",\n    name: \"Hot Wheels Classic Red Racer\",\n    series: \"Vintage Racing Club\",\n    year: 2025,\n    condition: \"Sealed Pack\",\n    price: 699,\n    stock: 1,\n    image: \"assets/catalog/classic-red-racer.jpg\",\n    imageAlt: \"Sealed Hot Wheels classic red race car\",\n    color: \"#242424\",\n    bg: \"#f8f7f3\",\n    glass: \"#ffffff\",\n    notes: \"Single sealed Hot Wheels pack with actual product photo.\"\n  },\n  {\n    id: \"classic-orange-pickup\",\n    name: \"Hot Wheels Classic Orange Pickup\",\n    series: \"Vintage Racing Club\",\n    year: 2025,\n    condition: \"Sealed Pack\",\n    price: 699,\n    stock: 1,\n    image: \"assets/catalog/classic-orange-pickup.jpg\",\n    imageAlt: \"Sealed Hot Wheels classic orange pickup\",\n    color: \"#242424\",\n    bg: \"#f8f7f3\",\n    glass: \"#ffffff\",\n    notes: \"Single sealed Hot Wheels pack with actual product photo.\"\n  },\n  {\n    id: \"assorted-jdm-3-pack\",\n    name: \"Hot Wheels JDM Sealed 3-Pack\",\n    series: \"Assorted Hot Wheels\",\n    year: 2025,\n    condition: \"Sealed Pack\",\n    price: 1199,\n    stock: 1,\n    image: \"assets/catalog/jdm-3-pack.jpg\",\n    imageAlt: \"Three sealed Hot Wheels JDM-style packs\",\n    color: \"#242424\",\n    bg: \"#f8f7f3\",\n    glass: \"#ffffff\",\n    notes: \"Three sealed Hot Wheels packs photographed from the actual available stock.\"\n  },\n  {\n    id: \"assorted-city-3-pack\",\n    name: \"Hot Wheels City Sealed 3-Pack\",\n    series: \"Assorted Hot Wheels\",\n    year: 2025,\n    condition: \"Sealed Pack\",\n    price: 1199,\n    stock: 1,\n    image: \"assets/catalog/city-3-pack.jpg\",\n    imageAlt: \"Three sealed Hot Wheels city vehicle packs\",\n    color: \"#242424\",\n    bg: \"#f8f7f3\",\n    glass: \"#ffffff\",\n    notes: \"Three sealed Hot Wheels packs photographed from the actual available stock.\"\n  },\n  {\n    id: \"classic-silver-wagon\",\n    name: \"Hot Wheels Classic Silver Wagon\",\n    series: \"Vintage Racing Club\",\n    year: 2025,\n    condition: \"Sealed Pack\",\n    price: 699,\n    stock: 1,\n    image: \"assets/catalog/classic-silver-wagon.jpg\",\n    imageAlt: \"Sealed Hot Wheels classic silver wagon\",\n    color: \"#242424\",\n    bg: \"#f8f7f3\",\n    glass: \"#ffffff\",\n    notes: \"Single sealed Hot Wheels pack with actual product photo.\"\n  },\n  {\n    id: \"assorted-character-3-pack\",\n    name: \"Hot Wheels Character & Concept 3-Pack\",\n    series: \"Assorted Hot Wheels\",\n    year: 2025,\n    condition: \"Sealed Pack\",\n    price: 1199,\n    stock: 1,\n    image: \"assets/catalog/character-concept-3-pack.jpg\",\n    imageAlt: \"Three sealed Hot Wheels character and concept vehicle packs\",\n    color: \"#242424\",\n    bg: \"#f8f7f3\",\n    glass: \"#ffffff\",\n    notes: \"Three sealed Hot Wheels packs photographed from the actual available stock.\"\n  },\n  {\n    id: \"assorted-performance-3-pack\",\n    name: \"Hot Wheels Performance Sealed 3-Pack\",\n    series: \"Assorted Hot Wheels\",\n    year: 2025,\n    condition: \"Sealed Pack\",\n    price: 1199,\n    stock: 1,\n    image: \"assets/catalog/performance-3-pack.jpg\",\n    imageAlt: \"Three sealed Hot Wheels performance vehicle packs\",\n    color: \"#242424\",\n    bg: \"#f8f7f3\",\n    glass: \"#ffffff\",\n    notes: \"Three sealed Hot Wheels packs photographed from the actual available stock.\"\n  },\n  {\n    id: \"batman-barbie-2-pack\",\n    name: \"Hot Wheels Batman & Barbie 2-Pack\",\n    series: \"Character Cars\",\n    year: 2025,\n    condition: \"Sealed Pack\",\n    price: 999,\n    stock: 1,\n    image: \"assets/catalog/batman-barbie-2-pack.jpg\",\n    imageAlt: \"Two sealed Hot Wheels Batman and Barbie themed packs\",\n    color: \"#242424\",\n    bg: \"#f8f7f3\",\n    glass: \"#ffffff\",\n    notes: \"Two sealed themed Hot Wheels packs photographed from the actual available stock.\"\n  }\n];\n\nfunction loadAdminProducts() {\n  try {\n    return JSON.parse(localStorage.getItem(\"zenzoAdminProducts\") || \"[]\");\n  } catch {\n    return [];\n  }\n}\n\nlet inventory = [...baseInventory, ...loadAdminProducts()];\n\nconst state = {\n  query: \"\",\n  collection: \"all\",\n  condition: \"all\",\n  sort: \"featured\",\n  cart: JSON.parse(localStorage.getItem(\"dieCastGarageCart\") || \"[]\")\n};\n\nconst productGrid = document.querySelector(\"#productGrid\");\nconst emptyState = document.querySelector(\"#emptyState\");\nconst searchInput = document.querySelector(\"#searchInput\");\nconst sortSelect = document.querySelector(\"#sortSelect\");\nconst cartPanel = document.querySelector(\"#cartPanel\");\nconst cartButton = document.querySelector(\"#cartButton\");\nconst closeCart = document.querySelector(\"#closeCart\");\nconst scrim = document.querySelector(\"#scrim\");\nconst cartCount = document.querySelector(\"#cartCount\");\nconst cartItems = document.querySelector(\"#cartItems\");\nconst cartSubtotal = document.querySelector(\"#cartSubtotal\");\nconst checkoutLink = document.querySelector(\"#checkoutLink\");\n\nconst money = new Intl.NumberFormat(\"en-US\", {\n  style: \"currency\",\n  currency: \"INR\",\n  maximumFractionDigits: 0\n});\n\nconst assetVersion = \"zenzo-race-theme-18\";\n\nfunction productCollection(product) {\n  return product.collection || \"Hot Wheels\";\n}\n\nasync function loadProductsFromApi() {\n  try {\n    const response = await fetch(\"/api/products\");\n    if (!response.ok) throw new Error(\"Products API unavailable.\");\n    inventory = await response.json();\n  } catch {\n    inventory = [...baseInventory, ...loadAdminProducts()];\n  }\n}\n\nfunction filteredInventory() {\n  const query = state.query.trim().toLowerCase();\n  const cars = inventory.filter((car) => {\n    const matchesCollection = state.collection === \"all\" || productCollection(car) === state.collection;\n    const matchesCondition = state.condition === \"all\" || car.condition === state.condition;\n    const haystack = `${car.name} ${productCollection(car)} ${car.series} ${car.year} ${car.condition}`.toLowerCase();\n    return matchesCollection && matchesCondition && haystack.includes(query);\n  });\n\n  return cars.sort((a, b) => {\n    if (state.sort === \"priceAsc\") return a.price - b.price;\n    if (state.sort === \"priceDesc\") return b.price - a.price;\n    if (state.sort === \"yearDesc\") return b.year - a.year;\n    return inventory.indexOf(a) - inventory.indexOf(b);\n  });\n}\n\nfunction cartQuantity(id) {\n  return state.cart.filter((itemId) => itemId === id).length;\n}\n\nfunction carMarkup(car) {\n  const inCart = cartQuantity(car.id);\n  const remaining = car.stock - inCart;\n  const stockLabel = car.stock > 1 ? `${remaining} of ${car.stock} left` : remaining > 0 ? \"1 available\" : \"Sold out\";\n  const buttonText = remaining > 0 ? inCart > 0 ? \"Add another\" : \"Add to cart\" : \"Sold out\";\n  const imageSrc = car.image && car.image.startsWith(\"data:\") ? car.image : `${car.image}?v=${assetVersion}`;\n  const detailsHref = `product.html?id=${encodeURIComponent(car.id)}`;\n  const media = car.image ? `<img class=\"product-photo\" src=\"${imageSrc}\" alt=\"${car.imageAlt || car.name}\" onerror=\"this.hidden = true; this.nextElementSibling.hidden = false;\"><span class=\"photo-fallback\" hidden>Photo unavailable</span>` : `\n        <div class=\"toy-car\" aria-hidden=\"true\">\n          <div class=\"toy-car__roof\"></div>\n          <div class=\"toy-car__body\"></div>\n          <div class=\"toy-car__stripe\"></div>\n          <div class=\"toy-car__wheel\"></div>\n          <div class=\"toy-car__wheel\"></div>\n        </div>\n  `;\n\n  return `\n    <article class=\"product-card\" data-details=\"${detailsHref}\">\n      <a class=\"product-link product-media\" href=\"${detailsHref}\" style=\"--car: ${car.color}; --car-bg: ${car.bg}; --glass: ${car.glass};\" aria-label=\"View ${car.name}\">\n        ${media}\n      </a>\n      <div class=\"product-info\">\n        <a class=\"product-title-link\" href=\"${detailsHref}\">\n          <div class=\"product-topline\">\n            <h3>${car.name}</h3>\n          </div>\n        </a>\n        <div class=\"product-actions-row\">\n          <span class=\"price\">${money.format(car.price)}</span>\n        </div>\n        <p class=\"meta\">\n          <span>${productCollection(car)}</span>\n          <span>${car.series}</span>\n          <span>${car.year}</span>\n          <span>${car.condition}</span>\n          <span>${stockLabel}</span>\n        </p>\n        <a class=\"details-link\" href=\"${detailsHref}\">View details</a>\n        <button class=\"add-button\" type=\"button\" data-add=\"${car.id}\" ${remaining <= 0 ? \"disabled\" : \"\"}>${buttonText}</button>\n      </div>\n    </article>\n  `;\n}\n\nfunction renderProducts() {\n  const cars = filteredInventory();\n  productGrid.innerHTML = cars.map(carMarkup).join(\"\");\n  emptyState.hidden = cars.length > 0;\n}\n\nfunction renderCart() {\n  localStorage.setItem(\"dieCastGarageCart\", JSON.stringify(state.cart));\n  cartCount.textContent = state.cart.length;\n  const subtotal = state.cart.reduce((sum, id) => {\n    const car = inventory.find((item) => item.id === id);\n    return sum + (car ? car.price : 0);\n  }, 0);\n\n  if (!state.cart.length) {\n    cartItems.innerHTML = '<p class=\"empty-state\">Your cart is empty.</p>';\n  } else {\n    cartItems.innerHTML = [...new Set(state.cart)].map((id) => {\n      const car = inventory.find((item) => item.id === id);\n      const quantity = cartQuantity(id);\n      return `\n        <div class=\"cart-item\">\n          <div>\n            <h3>${car.name}</h3>\n            <p>${car.condition} &middot; ${car.series} &middot; Qty ${quantity}</p>\n          </div>\n          <strong>${money.format(car.price * quantity)}</strong>\n          <button class=\"remove-button\" type=\"button\" data-remove=\"${car.id}\">Remove</button>\n        </div>\n      `;\n    }).join(\"\");\n  }\n\n  cartSubtotal.textContent = money.format(subtotal);\n  checkoutLink.href = state.cart.length ? \"checkout.html\" : \"#catalog\";\n}\n\nfunction openCart() {\n  cartPanel.classList.add(\"is-open\");\n  cartPanel.setAttribute(\"aria-hidden\", \"false\");\n  cartButton.setAttribute(\"aria-expanded\", \"true\");\n  scrim.hidden = false;\n}\n\nfunction hideCart() {\n  cartPanel.classList.remove(\"is-open\");\n  cartPanel.setAttribute(\"aria-hidden\", \"true\");\n  cartButton.setAttribute(\"aria-expanded\", \"false\");\n  scrim.hidden = true;\n}\n\nproductGrid.addEventListener(\"click\", (event) => {\n  const button = event.target.closest(\"[data-add]\");\n  if (!button) {\n    const card = event.target.closest(\"[data-details]\");\n    if (card && !event.target.closest(\"a\")) window.location.href = card.dataset.details;\n    return;\n  }\n  const car = inventory.find((item) => item.id === button.dataset.add);\n  if (!car || cartQuantity(car.id) >= car.stock) return;\n  state.cart.push(car.id);\n  renderProducts();\n  renderCart();\n  openCart();\n});\n\ncartItems.addEventListener(\"click\", (event) => {\n  const button = event.target.closest(\"[data-remove]\");\n  if (!button) return;\n  const index = state.cart.indexOf(button.dataset.remove);\n  if (index >= 0) state.cart.splice(index, 1);\n  renderProducts();\n  renderCart();\n});\n\ndocument.querySelectorAll(\"[data-condition]\").forEach((button) => {\n  button.addEventListener(\"click\", () => {\n    state.condition = button.dataset.condition;\n    document.querySelectorAll(\"[data-condition]\").forEach((chip) => chip.classList.toggle(\"is-active\", chip === button));\n    renderProducts();\n  });\n});\n\ndocument.querySelectorAll(\"[data-collection]\").forEach((button) => {\n  button.addEventListener(\"click\", () => {\n    state.collection = button.dataset.collection;\n    document.querySelectorAll(\"[data-collection]\").forEach((card) => card.classList.toggle(\"is-active\", card === button));\n    renderProducts();\n  });\n});\n\nsearchInput.addEventListener(\"input\", () => {\n  state.query = searchInput.value;\n  renderProducts();\n});\n\nsortSelect.addEventListener(\"change\", () => {\n  state.sort = sortSelect.value;\n  renderProducts();\n});\n\ncartButton.addEventListener(\"click\", openCart);\ncloseCart.addEventListener(\"click\", hideCart);\nscrim.addEventListener(\"click\", hideCart);\n\ndocument.addEventListener(\"keydown\", (event) => {\n  if (event.key === \"Escape\") hideCart();\n});\n\nasync function init() {\n  await loadProductsFromApi();\n  renderProducts();\n  renderCart();\n}\n\ninit();\n","type":"text/javascript; charset=utf-8"},"/product.js":{"body":"const baseInventory = [\n  {\n    id: \"f1-race-team-5-pack\",\n    name: \"Hot Wheels Formula 1 Race Team 5-Pack\",\n    series: \"Formula 1 Collection\",\n    year: 2025,\n    condition: \"Sealed Pack\",\n    price: 1499,\n    stock: 7,\n    image: \"assets/catalog/f1-5-pack.jpg\",\n    imageAlt: \"Hot Wheels Formula 1 Race Team 5-Pack in retail packaging\",\n    notes: \"Set of 5 Formula 1-themed 1:64 die-cast race cars. New carded packs; 7 available.\"\n  },\n  {\n    id: \"mystery-models-foil-pack\",\n    name: \"Hot Wheels Mystery Models Foil Pack\",\n    series: \"Mystery Models\",\n    year: 2025,\n    condition: \"Sealed\",\n    price: 249,\n    stock: 25,\n    image: \"assets/catalog/mystery-models.jpg\",\n    imageAlt: \"Hot Wheels Mystery Models sealed foil pack\",\n    notes: \"Sealed surprise pack with one 1:64 Hot Wheels vehicle and matching sticker inside. 25 available.\"\n  },\n  {\n    id: \"assorted-2-pack-blue-orange\",\n    name: \"Hot Wheels Blue & Orange Sealed 2-Pack\",\n    series: \"Assorted Hot Wheels\",\n    year: 2025,\n    condition: \"Sealed Pack\",\n    price: 899,\n    stock: 1,\n    image: \"assets/catalog/blue-orange-2-pack.jpg\",\n    imageAlt: \"Two sealed Hot Wheels packs with blue and orange cars\",\n    notes: \"Two sealed Hot Wheels packs photographed from the actual available stock.\"\n  },\n  {\n    id: \"assorted-3-pack-sports-cars\",\n    name: \"Hot Wheels Sports Car Sealed 3-Pack\",\n    series: \"Assorted Hot Wheels\",\n    year: 2025,\n    condition: \"Sealed Pack\",\n    price: 1199,\n    stock: 1,\n    image: \"assets/catalog/sports-car-3-pack.jpg\",\n    imageAlt: \"Three sealed Hot Wheels sports car packs\",\n    notes: \"Three sealed Hot Wheels packs photographed from the actual available stock.\"\n  },\n  {\n    id: \"classic-black-racer\",\n    name: \"Hot Wheels Classic Black Racer\",\n    series: \"Vintage Racing Club\",\n    year: 2025,\n    condition: \"Sealed Pack\",\n    price: 699,\n    stock: 1,\n    image: \"assets/catalog/classic-black-racer.jpg\",\n    imageAlt: \"Sealed Hot Wheels classic black race car\",\n    notes: \"Single sealed Hot Wheels pack with actual product photo.\"\n  },\n  {\n    id: \"classic-red-racer\",\n    name: \"Hot Wheels Classic Red Racer\",\n    series: \"Vintage Racing Club\",\n    year: 2025,\n    condition: \"Sealed Pack\",\n    price: 699,\n    stock: 1,\n    image: \"assets/catalog/classic-red-racer.jpg\",\n    imageAlt: \"Sealed Hot Wheels classic red race car\",\n    notes: \"Single sealed Hot Wheels pack with actual product photo.\"\n  },\n  {\n    id: \"classic-orange-pickup\",\n    name: \"Hot Wheels Classic Orange Pickup\",\n    series: \"Vintage Racing Club\",\n    year: 2025,\n    condition: \"Sealed Pack\",\n    price: 699,\n    stock: 1,\n    image: \"assets/catalog/classic-orange-pickup.jpg\",\n    imageAlt: \"Sealed Hot Wheels classic orange pickup\",\n    notes: \"Single sealed Hot Wheels pack with actual product photo.\"\n  },\n  {\n    id: \"assorted-jdm-3-pack\",\n    name: \"Hot Wheels JDM Sealed 3-Pack\",\n    series: \"Assorted Hot Wheels\",\n    year: 2025,\n    condition: \"Sealed Pack\",\n    price: 1199,\n    stock: 1,\n    image: \"assets/catalog/jdm-3-pack.jpg\",\n    imageAlt: \"Three sealed Hot Wheels JDM-style packs\",\n    notes: \"Three sealed Hot Wheels packs photographed from the actual available stock.\"\n  },\n  {\n    id: \"assorted-city-3-pack\",\n    name: \"Hot Wheels City Sealed 3-Pack\",\n    series: \"Assorted Hot Wheels\",\n    year: 2025,\n    condition: \"Sealed Pack\",\n    price: 1199,\n    stock: 1,\n    image: \"assets/catalog/city-3-pack.jpg\",\n    imageAlt: \"Three sealed Hot Wheels city vehicle packs\",\n    notes: \"Three sealed Hot Wheels packs photographed from the actual available stock.\"\n  },\n  {\n    id: \"classic-silver-wagon\",\n    name: \"Hot Wheels Classic Silver Wagon\",\n    series: \"Vintage Racing Club\",\n    year: 2025,\n    condition: \"Sealed Pack\",\n    price: 699,\n    stock: 1,\n    image: \"assets/catalog/classic-silver-wagon.jpg\",\n    imageAlt: \"Sealed Hot Wheels classic silver wagon\",\n    notes: \"Single sealed Hot Wheels pack with actual product photo.\"\n  },\n  {\n    id: \"assorted-character-3-pack\",\n    name: \"Hot Wheels Character & Concept 3-Pack\",\n    series: \"Assorted Hot Wheels\",\n    year: 2025,\n    condition: \"Sealed Pack\",\n    price: 1199,\n    stock: 1,\n    image: \"assets/catalog/character-concept-3-pack.jpg\",\n    imageAlt: \"Three sealed Hot Wheels character and concept vehicle packs\",\n    notes: \"Three sealed Hot Wheels packs photographed from the actual available stock.\"\n  },\n  {\n    id: \"assorted-performance-3-pack\",\n    name: \"Hot Wheels Performance Sealed 3-Pack\",\n    series: \"Assorted Hot Wheels\",\n    year: 2025,\n    condition: \"Sealed Pack\",\n    price: 1199,\n    stock: 1,\n    image: \"assets/catalog/performance-3-pack.jpg\",\n    imageAlt: \"Three sealed Hot Wheels performance vehicle packs\",\n    notes: \"Three sealed Hot Wheels packs photographed from the actual available stock.\"\n  },\n  {\n    id: \"batman-barbie-2-pack\",\n    name: \"Hot Wheels Batman & Barbie 2-Pack\",\n    series: \"Character Cars\",\n    year: 2025,\n    condition: \"Sealed Pack\",\n    price: 999,\n    stock: 1,\n    image: \"assets/catalog/batman-barbie-2-pack.jpg\",\n    imageAlt: \"Two sealed Hot Wheels Batman and Barbie themed packs\",\n    notes: \"Two sealed themed Hot Wheels packs photographed from the actual available stock.\"\n  }\n];\n\nfunction loadAdminProducts() {\n  try {\n    return JSON.parse(localStorage.getItem(\"zenzoAdminProducts\") || \"[]\");\n  } catch {\n    return [];\n  }\n}\n\nlet inventory = [...baseInventory, ...loadAdminProducts()];\nconst productDetail = document.querySelector(\"#productDetail\");\nconst params = new URLSearchParams(window.location.search);\nlet product = inventory.find((item) => item.id === params.get(\"id\"));\nconst money = new Intl.NumberFormat(\"en-US\", {\n  style: \"currency\",\n  currency: \"INR\",\n  maximumFractionDigits: 0\n});\nconst assetVersion = \"zenzo-race-theme-18\";\n\nfunction productCollection(item) {\n  return item.collection || \"Hot Wheels\";\n}\n\nasync function loadProductsFromApi() {\n  try {\n    const response = await fetch(\"/api/products\");\n    if (!response.ok) throw new Error(\"Products API unavailable.\");\n    inventory = await response.json();\n    product = inventory.find((item) => item.id === params.get(\"id\"));\n  } catch {\n    inventory = [...baseInventory, ...loadAdminProducts()];\n    product = inventory.find((item) => item.id === params.get(\"id\"));\n  }\n}\n\nfunction getCart() {\n  return JSON.parse(localStorage.getItem(\"dieCastGarageCart\") || \"[]\");\n}\n\nfunction setCart(cart) {\n  localStorage.setItem(\"dieCastGarageCart\", JSON.stringify(cart));\n}\n\nfunction cartQuantity(id) {\n  return getCart().filter((itemId) => itemId === id).length;\n}\n\nfunction renderMissingProduct() {\n  productDetail.innerHTML = `\n    <div class=\"checkout-panel\">\n      <div class=\"checkout-panel__body\">\n        <p class=\"eyebrow\">Product</p>\n        <h1>Listing not found</h1>\n        <p class=\"checkout-note\">This product may have moved or been removed.</p>\n        <a class=\"primary-link\" href=\"index.html#catalog\">Back to current listings</a>\n      </div>\n    </div>\n  `;\n}\n\nfunction renderProduct() {\n  const inCart = cartQuantity(product.id);\n  const remaining = product.stock - inCart;\n  const stockLabel = product.stock > 1 ? `${remaining} of ${product.stock} left` : remaining > 0 ? \"1 available\" : \"Sold out\";\n  const buttonText = remaining > 0 ? inCart > 0 ? \"Add another\" : \"Add to cart\" : \"Sold out\";\n  const imageSrc = product.image && product.image.startsWith(\"data:\") ? product.image : `${product.image}?v=${assetVersion}`;\n  document.title = `${product.name} | Zenzo`;\n\n  productDetail.innerHTML = `\n    <div class=\"product-detail__media\">\n      <img src=\"${imageSrc}\" alt=\"${product.imageAlt || product.name}\" onerror=\"this.hidden = true; this.nextElementSibling.hidden = false;\">\n      <span class=\"photo-fallback\" hidden>Photo unavailable</span>\n    </div>\n    <div class=\"product-detail__info\">\n      <p class=\"eyebrow\">${productCollection(product)}</p>\n      <h1>${product.name}</h1>\n      <strong class=\"product-detail__price\">${money.format(product.price)}</strong>\n      <p class=\"meta\">\n        <span>${product.series}</span>\n        <span>${product.year}</span>\n        <span>${product.condition}</span>\n        <span>${stockLabel}</span>\n      </p>\n      <div class=\"detail-block\">\n        <h2>Description</h2>\n        <p>${product.notes}</p>\n      </div>\n      <div class=\"detail-block\">\n        <h2>Payment</h2>\n        <p>UPI payment is handled through secure checkout and confirmed before dispatch.</p>\n      </div>\n      <div class=\"product-detail__actions\">\n        <button class=\"add-button\" id=\"detailAddButton\" type=\"button\" ${remaining <= 0 ? \"disabled\" : \"\"}>${buttonText}</button>\n        <a class=\"checkout-link\" href=\"checkout.html\">Go to checkout</a>\n      </div>\n      <p class=\"checkout-note\" id=\"detailMessage\"></p>\n    </div>\n  `;\n}\n\nasync function init() {\n  await loadProductsFromApi();\n  if (!product) {\n    renderMissingProduct();\n    return;\n  }\n  renderProduct();\n  productDetail.addEventListener(\"click\", (event) => {\n    const button = event.target.closest(\"#detailAddButton\");\n    if (!button) return;\n    const cart = getCart();\n    if (cartQuantity(product.id) >= product.stock) return;\n    cart.push(product.id);\n    setCart(cart);\n    renderProduct();\n    const message = document.querySelector(\"#detailMessage\");\n    if (message) message.textContent = \"Added to cart.\";\n  });\n}\n\ninit();\n","type":"text/javascript; charset=utf-8"},"/checkout.js":{"body":"let inventory = [];\nconst cart = JSON.parse(localStorage.getItem(\"dieCastGarageCart\") || \"[]\");\nconst orderList = document.querySelector(\"#orderList\");\nconst subtotalEl = document.querySelector(\"#checkoutSubtotal\");\nconst form = document.querySelector(\"#checkoutForm\");\nconst checkoutNote = document.querySelector(\"#checkoutNote\");\nconst money = new Intl.NumberFormat(\"en-US\", {\n  style: \"currency\",\n  currency: \"INR\",\n  maximumFractionDigits: 0\n});\n\nasync function api(path, options = {}) {\n  const response = await fetch(path, {\n    headers: { \"content-type\": \"application/json\", ...(options.headers || {}) },\n    ...options\n  });\n  const data = await response.json();\n  if (!response.ok) throw new Error(data.error || \"Request failed.\");\n  return data;\n}\n\nfunction cartQuantity(id) {\n  return cart.filter((itemId) => itemId === id).length;\n}\n\nfunction getOrderLines() {\n  return [...new Set(cart)].map((id) => {\n    const item = inventory.find((product) => product.id === id);\n    const quantity = cartQuantity(id);\n    return { item, quantity };\n  }).filter((line) => line.item);\n}\n\nfunction getSubtotal(orderLines) {\n  return orderLines.reduce((sum, line) => sum + line.item.price * line.quantity, 0);\n}\n\nfunction renderCheckout() {\n  const orderLines = getOrderLines();\n  const subtotal = getSubtotal(orderLines);\n\n  if (!orderLines.length) {\n    orderList.innerHTML = '<p class=\"empty-state\">Your cart is empty.</p>';\n  } else {\n    orderList.innerHTML = orderLines.map(({ item, quantity }) => `\n      <div class=\"order-line\">\n        <div>\n          <h3>${item.name}</h3>\n          <p>${item.condition} &middot; Qty ${quantity}</p>\n        </div>\n        <strong>${money.format(item.price * quantity)}</strong>\n      </div>\n    `).join(\"\");\n  }\n\n  subtotalEl.textContent = money.format(subtotal);\n}\n\nfunction openRazorpay(order, formData) {\n  if (!window.Razorpay || !order.paymentConfigured) {\n    checkoutNote.textContent = \"Payment gateway keys are not configured yet. Add Razorpay live keys on the production server before taking payments.\";\n    return;\n  }\n\n  const razorpay = new window.Razorpay({\n    key: order.razorpayKeyId,\n    amount: order.amount,\n    currency: order.currency,\n    name: \"Zenzo\",\n    description: `Order ${order.orderId}`,\n    order_id: order.razorpayOrderId,\n    prefill: {\n      name: String(formData.get(\"name\") || \"\"),\n      email: String(formData.get(\"email\") || \"\"),\n      contact: String(formData.get(\"phone\") || \"\")\n    },\n    notes: {\n      order_id: order.orderId\n    },\n    theme: {\n      color: \"#242424\"\n    },\n    handler() {\n      localStorage.removeItem(\"dieCastGarageCart\");\n      checkoutNote.textContent = \"Payment received. Zenzo will confirm and dispatch your order.\";\n      form.reset();\n      orderList.innerHTML = '<p class=\"empty-state\">Payment received. Your cart is now clear.</p>';\n      subtotalEl.textContent = money.format(0);\n    }\n  });\n  razorpay.open();\n}\n\nform.addEventListener(\"submit\", async (event) => {\n  event.preventDefault();\n  const orderLines = getOrderLines();\n\n  if (!orderLines.length) {\n    alert(\"Your cart is empty. Please add a product before checkout.\");\n    return;\n  }\n\n  const formData = new FormData(form);\n  checkoutNote.textContent = \"Preparing secure checkout...\";\n\n  try {\n    const order = await api(\"/api/orders\", {\n      method: \"POST\",\n      body: JSON.stringify({\n        cart,\n        customer: {\n          name: formData.get(\"name\"),\n          email: formData.get(\"email\"),\n          phone: formData.get(\"phone\")\n        },\n        shipping: {\n          address: formData.get(\"address\"),\n          city: formData.get(\"city\"),\n          state: formData.get(\"state\"),\n          pin: formData.get(\"pin\")\n        }\n      })\n    });\n    openRazorpay(order, formData);\n  } catch (error) {\n    checkoutNote.textContent = error.message;\n  }\n});\n\nasync function init() {\n  try {\n    inventory = await api(\"/api/products\");\n  } catch {\n    inventory = [];\n  }\n  renderCheckout();\n}\n\ninit();\n","type":"text/javascript; charset=utf-8"},"/admin.js":{"body":"const loginPanel = document.querySelector(\"#loginPanel\");\nconst loginForm = document.querySelector(\"#loginForm\");\nconst loginMessage = document.querySelector(\"#loginMessage\");\nconst dashboard = document.querySelector(\"#adminDashboard\");\nconst productForm = document.querySelector(\"#productForm\");\nconst productsList = document.querySelector(\"#adminProducts\");\nconst logoutButton = document.querySelector(\"#logoutButton\");\n\nconst money = new Intl.NumberFormat(\"en-US\", {\n  style: \"currency\",\n  currency: \"INR\",\n  maximumFractionDigits: 0\n});\n\nasync function api(path, options = {}) {\n  const response = await fetch(path, {\n    credentials: \"same-origin\",\n    headers: { \"content-type\": \"application/json\", ...(options.headers || {}) },\n    ...options\n  });\n  const data = await response.json();\n  if (!response.ok) throw new Error(data.error || \"Request failed.\");\n  return data;\n}\n\nfunction showDashboard() {\n  loginPanel.hidden = true;\n  dashboard.hidden = false;\n  renderProducts();\n}\n\nfunction showLogin() {\n  loginPanel.hidden = false;\n  dashboard.hidden = true;\n}\n\nfunction resizeImage(file) {\n  return new Promise((resolve, reject) => {\n    if (!file) {\n      resolve(\"\");\n      return;\n    }\n\n    const reader = new FileReader();\n    reader.onerror = reject;\n    reader.onload = () => {\n      const img = new Image();\n      img.onerror = reject;\n      img.onload = () => {\n        const maxSize = 1100;\n        const scale = Math.min(1, maxSize / Math.max(img.width, img.height));\n        const canvas = document.createElement(\"canvas\");\n        canvas.width = Math.round(img.width * scale);\n        canvas.height = Math.round(img.height * scale);\n        const ctx = canvas.getContext(\"2d\");\n        ctx.fillStyle = \"#f8f7f3\";\n        ctx.fillRect(0, 0, canvas.width, canvas.height);\n        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);\n        resolve(canvas.toDataURL(\"image/jpeg\", 0.82));\n      };\n      img.src = reader.result;\n    };\n    reader.readAsDataURL(file);\n  });\n}\n\nasync function renderProducts() {\n  let products = [];\n  try {\n    products = await api(\"/api/products\");\n  } catch (error) {\n    productsList.innerHTML = `<p class=\"empty-state\">${error.message}</p>`;\n    return;\n  }\n\n  if (!products.length) {\n    productsList.innerHTML = '<p class=\"empty-state\">No products added yet.</p>';\n    return;\n  }\n\n  productsList.innerHTML = products.map((product) => `\n    <div class=\"admin-product\">\n      ${product.image ? `<img src=\"${product.image}\" alt=\"${product.name}\">` : \"\"}\n      <div>\n        <h3>${product.name}</h3>\n        <p>${product.collection || \"Hot Wheels\"} &middot; ${product.series} &middot; ${product.condition} &middot; ${money.format(product.price)} &middot; Stock ${product.stock}</p>\n      </div>\n      <button class=\"remove-button\" type=\"button\" data-delete=\"${product.id}\">Delete</button>\n    </div>\n  `).join(\"\");\n}\n\nloginForm.addEventListener(\"submit\", async (event) => {\n  event.preventDefault();\n  const form = new FormData(loginForm);\n  try {\n    await api(\"/api/admin/login\", {\n      method: \"POST\",\n      body: JSON.stringify({\n        email: form.get(\"email\"),\n        password: form.get(\"password\")\n      })\n    });\n    loginMessage.textContent = \"\";\n    showDashboard();\n  } catch (error) {\n    loginMessage.textContent = error.message;\n  }\n});\n\nproductForm.addEventListener(\"submit\", async (event) => {\n  event.preventDefault();\n  const form = new FormData(productForm);\n  const name = String(form.get(\"name\") || \"\").trim();\n  const image = await resizeImage(productForm.elements.image.files[0]);\n\n  try {\n    await api(\"/api/admin/products\", {\n      method: \"POST\",\n      body: JSON.stringify({\n        name,\n        collection: form.get(\"collection\"),\n        series: form.get(\"series\"),\n        year: form.get(\"year\"),\n        condition: form.get(\"condition\"),\n        price: form.get(\"price\"),\n        stock: form.get(\"stock\"),\n        image,\n        imageAlt: name,\n        notes: form.get(\"notes\")\n      })\n    });\n    productForm.reset();\n    productForm.elements.collection.value = \"Hot Wheels\";\n    productForm.elements.series.value = \"Assorted Hot Wheels\";\n    productForm.elements.year.value = \"2025\";\n    productForm.elements.stock.value = \"1\";\n    productForm.elements.notes.value = \"Sealed Hot Wheels pack photographed from available stock.\";\n    renderProducts();\n  } catch (error) {\n    alert(error.message);\n  }\n});\n\nproductsList.addEventListener(\"click\", async (event) => {\n  const button = event.target.closest(\"[data-delete]\");\n  if (!button) return;\n  try {\n    await api(`/api/admin/products/${encodeURIComponent(button.dataset.delete)}`, { method: \"DELETE\" });\n    renderProducts();\n  } catch (error) {\n    alert(error.message);\n  }\n});\n\nlogoutButton.addEventListener(\"click\", async () => {\n  await api(\"/api/admin/logout\", { method: \"POST\" });\n  showLogin();\n});\n\nasync function init() {\n  try {\n    const session = await api(\"/api/admin/session\");\n    if (session.authenticated) {\n      showDashboard();\n      return;\n    }\n  } catch {\n    // Fall through to login.\n  }\n  showLogin();\n}\n\ninit();\n","type":"text/javascript; charset=utf-8"},"/":{"body":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>Zenzo</title>\n    <meta name=\"description\" content=\"Collector storefront for selling Hot Wheels and 1:64 die-cast cars.\">\n    <link rel=\"preload\" as=\"image\" href=\"assets/hero-shelf-fast.jpg\">\n    <link rel=\"preload\" as=\"image\" href=\"assets/zenzo-logo-mark.png\">\n    <link rel=\"stylesheet\" href=\"styles.css?v=zenzo-race-theme-18\">\n  </head>\n  <body>\n    <header class=\"hero\">\n      <img src=\"assets/hero-shelf-fast.jpg\" alt=\"Display shelf with collectible die-cast toy cars\" class=\"hero__image\" width=\"1280\" height=\"683\" fetchpriority=\"high\">\n      <div class=\"hero__shade\"></div>\n      <nav class=\"topbar\" aria-label=\"Primary navigation\">\n        <a class=\"brand\" href=\"#catalog\" aria-label=\"Zenzo home\">\n          <span class=\"brand__logo-frame\"><img src=\"assets/zenzo-logo-mark.png\" alt=\"Zenzo\" class=\"brand__logo\" width=\"520\" height=\"138\" fetchpriority=\"high\"></span>\n        </a>\n        <button class=\"cart-button\" id=\"cartButton\" type=\"button\" aria-controls=\"cartPanel\" aria-expanded=\"false\">\n          <span aria-hidden=\"true\">Cart</span>\n          <span class=\"cart-button__count\" id=\"cartCount\">0</span>\n        </button>\n      </nav>\n      <section class=\"hero__content\" aria-labelledby=\"pageTitle\">\n        <h1 id=\"pageTitle\" class=\"hero__headline\">\n          <span class=\"hero__line hero__line--primary\">Race-ready</span>\n          <span class=\"hero__line hero__line--accent\">Hot Wheels</span>\n        </h1>\n        <div class=\"hero__motion\" aria-hidden=\"true\">\n          <span></span>\n          <span></span>\n          <span></span>\n        </div>\n        <p class=\"hero__copy\">Your one-stop destination for collectibles. Explore Hot Wheels, figurines, and 3D printed collectibles, from iconic diecast cars to custom designed display pieces.</p>\n        <p class=\"hero__tagline\">Built for collectors, by collectors.</p>\n        <a class=\"primary-link\" href=\"#catalog\">Shop the drop</a>\n      </section>\n    </header>\n\n    <main>\n      <section class=\"showcase\" aria-labelledby=\"showcaseTitle\">\n        <div class=\"showcase__copy\">\n          <p class=\"eyebrow\">Collector display</p>\n          <h2 id=\"showcaseTitle\">Fresh drops, shelf-ready pieces</h2>\n          <p>Browse sealed packs and collectible 1:64 finds curated for Indian buyers.</p>\n        </div>\n        <img src=\"assets/collector-shelf-v2.png?v=zenzo-race-theme-18\" alt=\"Collector shelf with die-cast toy cars and sealed packs\" loading=\"lazy\">\n      </section>\n\n      <section class=\"collections\" aria-labelledby=\"collectionsTitle\">\n        <div class=\"collections__intro\">\n          <p class=\"eyebrow\">Collections</p>\n          <h2 id=\"collectionsTitle\">Browse collections</h2>\n        </div>\n        <div class=\"collection-list\" aria-label=\"Collection filter\">\n          <button class=\"collection-card collection-card--all is-active\" type=\"button\" data-collection=\"all\">\n            <strong>All collectibles</strong>\n          </button>\n          <button class=\"collection-card collection-card--hotwheels\" type=\"button\" data-collection=\"Hot Wheels\">\n            <strong>Hot Wheels</strong>\n          </button>\n          <button class=\"collection-card collection-card--figurines\" type=\"button\" data-collection=\"Figurines\">\n            <strong>Figurines</strong>\n          </button>\n          <button class=\"collection-card collection-card--printed\" type=\"button\" data-collection=\"3D collectibles\">\n            <strong>3D collectibles</strong>\n          </button>\n        </div>\n      </section>\n\n      <section class=\"toolbar\" aria-label=\"Catalog controls\">\n        <label class=\"search\">\n          <span class=\"sr-only\">Search cars</span>\n          <input id=\"searchInput\" type=\"search\" placeholder=\"Search name, collection, series\">\n        </label>\n        <div class=\"filter-group\" aria-label=\"Condition filter\">\n          <button class=\"chip is-active\" type=\"button\" data-condition=\"all\">All</button>\n          <button class=\"chip\" type=\"button\" data-condition=\"Sealed Pack\">Sealed Pack</button>\n          <button class=\"chip\" type=\"button\" data-condition=\"Sealed\">Sealed</button>\n        </div>\n        <label class=\"select-label\">\n          <span class=\"sr-only\">Sort products</span>\n          <select id=\"sortSelect\">\n            <option value=\"featured\">Featured</option>\n            <option value=\"priceAsc\">Price low to high</option>\n            <option value=\"priceDesc\">Price high to low</option>\n            <option value=\"yearDesc\">Newest year</option>\n          </select>\n        </label>\n      </section>\n\n      <section class=\"catalog\" id=\"catalog\" aria-labelledby=\"catalogTitle\">\n        <div class=\"section-heading\">\n          <p class=\"eyebrow\">Available now</p>\n          <h2 id=\"catalogTitle\">Current listings</h2>\n        </div>\n        <div class=\"product-grid\" id=\"productGrid\"></div>\n        <p class=\"empty-state\" id=\"emptyState\" hidden>No matching cars found.</p>\n      </section>\n    </main>\n\n    <aside class=\"cart-panel\" id=\"cartPanel\" aria-label=\"Shopping cart\" aria-hidden=\"true\">\n      <div class=\"cart-panel__header\">\n        <h2>Your cart</h2>\n        <button class=\"icon-button\" id=\"closeCart\" type=\"button\" aria-label=\"Close cart\">x</button>\n      </div>\n      <div class=\"cart-items\" id=\"cartItems\"></div>\n      <div class=\"cart-summary\">\n        <div class=\"cart-summary__row\">\n          <span>Subtotal</span>\n          <strong id=\"cartSubtotal\">$0.00</strong>\n        </div>\n        <p>UPI payments are handled through secure checkout before dispatch.</p>\n        <a class=\"checkout-link\" id=\"checkoutLink\" href=\"checkout.html\">Checkout</a>\n      </div>\n    </aside>\n    <div class=\"scrim\" id=\"scrim\" hidden></div>\n\n    <footer>\n      <p>Zenzo collector resale shop. Not affiliated with Mattel or Hot Wheels.</p>\n      <a class=\"footer-admin-link\" href=\"admin.html\">Admin</a>\n    </footer>\n\n    <script src=\"app.js?v=zenzo-race-theme-18\"></script>\n  </body>\n</html>\n","type":"text/html; charset=utf-8"}};
